ini_set('session.use_strict_mode','1');session_name('PQINSTALLSID');session_set_cookie_params(['secure'=>$secure,'httponly'=>true,'samesite'=>'Strict']);session_start();$_SESSION['csrf']??=bin2hex(random_bytes(32));$error=null;$success=false;$checks=[];
